  useEffect(() => {
    if (pendingLink) {
      console.log("[sync:qr] pending deep link received");
      sync.setPendingLink(null);
      void applyLink(pendingLink);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pendingLink]);

